using System.Buffers.Binary;
using System.Text;
using System.Text.Json;
using ControlSpawn.Core;
using Xunit;

namespace ControlSpawn.Lighting.Tests;

public sealed class MiioTests
{
    // Published inputs: python-miio 0.5.12 test_decode_json_payload + build_msg.
    // https://github.com/rytilahti/python-miio/blob/0.5.12/miio/tests/test_protocol.py
    // The byte literal below was independently materialized with PowerShell AES/MD5,
    // not generated by MiioProtocol. Zero token, did 01234567, epoch 0, b'{"id": 123456}'.
    private const string KnownPacket = "21310030000000000123456700000000dbcfd26369cf65a172b5737cc131f6de754865dce4359d961e1bfee48e12817e";

    [Fact]
    public void HelloAndReplyHaveFixedBigEndianLayout()
    {
        Assert.Equal("21310020ffffffffffffffffffffffffffffffffffffffffffffffffffffffff", Convert.ToHexString(MiioProtocol.Hello()).ToLowerInvariant());
        var reply = Convert.FromHexString("21310020000000000123456701020304ffffffffffffffffffffffffffffffff");
        Assert.Equal(new MiioHeader(0x01234567, 0x01020304), MiioProtocol.ReadHeader(reply));
    }
    [Fact]
    public void PublishedFixtureInputsProduceKnownPacketAndDecode()
    {
        var token = new byte[16];
        Assert.Equal(KnownPacket, Convert.ToHexString(MiioProtocol.Encode(0x01234567, 0, token, "{\"id\": 123456}"u8)).ToLowerInvariant());
        Assert.Equal("{\"id\": 123456}", Encoding.UTF8.GetString(MiioProtocol.Decode(Convert.FromHexString(KnownPacket), token)));
    }
    [Fact]
    public void RoundTripHandlesUtf8AndPadding()
    {
        var token = Convert.FromHexString("00112233445566778899aabbccddeeff");
        var plain = Encoding.UTF8.GetBytes("{\"label\":\"温度\",\"params\":[1,true]}\0");
        Assert.Equal(plain, MiioProtocol.Decode(MiioProtocol.Encode(100, 42, token, plain), token));
    }
    [Theory]
    [InlineData(8)] [InlineData(16)] [InlineData(32)] [InlineData(47)]
    public void CorruptionIsRejected(int position)
    {
        var packet = Convert.FromHexString(KnownPacket); packet[position] ^= 1;
        Assert.Throws<InvalidDataException>(() => MiioProtocol.Decode(packet, new byte[16]));
    }
    [Fact]
    public void HeaderLengthAndTokenLengthAreValidated()
    {
        Assert.Throws<InvalidDataException>(() => MiioProtocol.ReadHeader(new byte[31]));
        var packet = Convert.FromHexString(KnownPacket); packet[3]++;
        Assert.Throws<InvalidDataException>(() => MiioProtocol.Decode(packet, new byte[16]));
        Assert.Throws<ArgumentException>(() => MiioProtocol.Encode(1, 1, new byte[15], "{}"u8));
    }

    private sealed class LampTransport(ManualClock clock) : IMiioTransport
    {
        public List<(TimeSpan Time, JsonElement Message, uint Stamp)> Requests { get; } = [];
        public int Hellos { get; private set; }
        public int Failures { get; set; }
        public Task<byte[]> ExchangeAsync(byte[] packet, CancellationToken cancellationToken)
        {
            Assert.True(cancellationToken.CanBeCanceled);
            if (packet.Length == 32)
            {
                Hellos++; var reply = MiioProtocol.Hello(); BinaryPrimitives.WriteUInt32BigEndian(reply.AsSpan(8), 123);
                BinaryPrimitives.WriteUInt32BigEndian(reply.AsSpan(12), 1000); return Task.FromResult(reply);
            }
            var header = MiioProtocol.ReadHeader(packet);
            using var json = JsonDocument.Parse(Encoding.UTF8.GetString(MiioProtocol.Decode(packet, new byte[16])).TrimEnd('\0'));
            Requests.Add((clock.Elapsed, json.RootElement.Clone(), header.Stamp));
            if (Failures-- > 0) throw new OperationCanceledException();
            return Task.FromResult(MiioProtocol.Encode(123, header.Stamp, new byte[16], JsonSerializer.SerializeToUtf8Bytes(new { id = json.RootElement.GetProperty("id").GetInt32(), result = new[] { "ok" } })));
        }
        public ValueTask DisposeAsync() => ValueTask.CompletedTask;
    }
    [Fact]
    public async Task MethodsStampAndGlobalRateLimitMatchLampModel()
    {
        var clock = new ManualClock(); var transport = new LampTransport(clock);
        await using var lamp = new MiioLampClient(transport, new byte[16], clock);
        await lamp.SetPowerAsync(true); await lamp.SetBrightnessAsync(60); await lamp.SetColorAsync(new(255, 77, 26));
        await lamp.SetColorTemperatureAsync(3500); await lamp.GetPropertiesAsync();
        Assert.Equal(new[] { "set_power", "set_bright", "set_rgb", "set_ct_abx", "get_prop" }, transport.Requests.Select(r => r.Message.GetProperty("method").GetString()));
        Assert.All(transport.Requests.Zip(transport.Requests.Skip(1)), pair => Assert.True(pair.Second.Time - pair.First.Time >= TimeSpan.FromMilliseconds(500)));
        Assert.Equal(1002u, transport.Requests.Last().Stamp);
        Assert.Equal("smooth", transport.Requests[2].Message.GetProperty("params")[1].GetString());
        Assert.Equal(500, transport.Requests[2].Message.GetProperty("params")[2].GetInt32());
        Assert.Equal(5, transport.Requests.Last().Message.GetProperty("params").GetArrayLength());
        await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() => lamp.SetBrightnessAsync(0));
    }
    [Fact]
    public async Task TimeoutRetriesRefreshHandshakeAndKeepRequestId()
    {
        var clock = new ManualClock(); var transport = new LampTransport(clock) { Failures = 2 };
        await using var lamp = new MiioLampClient(transport, new byte[16], clock);
        await lamp.SetPowerAsync(false);
        Assert.Equal(3, transport.Hellos); Assert.Equal(3, transport.Requests.Count);
        Assert.Single(transport.Requests.Select(r => r.Message.GetProperty("id").GetInt32()).Distinct());
        transport.Failures = 4;
        await Assert.ThrowsAsync<OperationCanceledException>(() => lamp.SetPowerAsync(false));
        Assert.Equal(6, transport.Requests.Count);
    }
    [Fact]
    public async Task CancellationDoesNotRetry()
    {
        var clock = new ManualClock(); var transport = new LampTransport(clock);
        await using var lamp = new MiioLampClient(transport, new byte[16], clock);
        using var stop = new CancellationTokenSource(); stop.Cancel();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => lamp.SetPowerAsync(true, stop.Token));
        Assert.Equal(0, transport.Hellos);
    }
    [Fact]
    public async Task FactoryPrefersLanThenTokenThenNotConfigured()
    {
        var clock = new ManualClock(); var connections = new FakeConnectionFactory();
        connections.Streams.Enqueue(new DuplexFixtureStream([]));
        var discovery = new YeelightDiscovery(new FakeDiscoveryTransport());
        var factory = new LampFactory(connections, discovery, clock, _ => new LampTransport(clock));
        var lan = await factory.CreateAsync("fixture", new byte[16]);
        Assert.IsType<YeelightClient>(lan.Client); await lan.Client!.DisposeAsync();
        var fallback = new LampFactory(new RefusedConnection(), discovery, clock, _ => new LampTransport(clock));
        var miio = await fallback.CreateAsync("fixture", new byte[16]);
        Assert.IsType<MiioLampClient>(miio.Client); await miio.Client!.DisposeAsync();
        Assert.Null((await fallback.CreateAsync("fixture", null)).Client);
    }
    private sealed class RefusedConnection : IConnectionFactory
    {
        public Task<Stream> ConnectAsync(string host, int port, CancellationToken token) => throw new IOException("Fake refused.");
    }
    private sealed class Protector : ILampSecretProtector
    {
        public byte[] Protect(byte[] value) => value.Select(b => (byte)(b ^ 0x55)).ToArray();
        public byte[] Unprotect(byte[] value) => Protect(value);
    }
    [Fact]
    public void TokenStoreUsesProtectorAndRejectsMalformedRecords()
    {
        var directory = Path.Combine(AppContext.BaseDirectory, "token-fixture-" + Guid.NewGuid());
        Directory.CreateDirectory(directory); var path = Path.Combine(directory, "lamp.json");
        try
        {
            var store = new LampTokenStore(path, new Protector()); var token = Enumerable.Range(0, 16).Select(i => (byte)i).ToArray();
            Assert.Null(store.Load()); store.Save(token); Assert.Equal(token, store.Load());
            Assert.DoesNotContain(Convert.ToHexString(token), File.ReadAllText(path));
            File.WriteAllText(path, "{}"); Assert.Null(store.Load());
            File.WriteAllText(path, "broken"); Assert.Null(store.Load());
        }
        finally { Directory.Delete(directory, true); }
    }
}
